import type { ReactNode } from 'react';
import { Inbox } from 'lucide-react';

interface EmptyStateProps {
  /** 自定义图标（默认 Inbox）；置于 48px 圆底内，尺寸建议 22px */
  icon?: ReactNode;
  title: string;
  description?: string;
  /** 次操作（设计稿 S-08：次按钮在主按钮左侧，如「清除筛选」） */
  secondaryAction?: ReactNode;
  /** 主操作（如「新建」/「邀请新用户」）；建议 Button size="sm" */
  primaryAction?: ReactNode;
}

/** 空态（S-08 空状态卡）：图标圈 + 标题 + 说明 + 可选主/次操作；四种语义（无数据/筛选无结果/无权限/失败）由调用方选文案 */
export function EmptyState({ icon, title, description, secondaryAction, primaryAction }: EmptyStateProps) {
  return (
    <div className="flex flex-col items-center justify-center gap-2.5 py-8 text-center">
      <div className="flex h-12 w-12 items-center justify-center rounded-full bg-muted text-muted-foreground">
        {icon ?? <Inbox className="h-[22px] w-[22px]" aria-hidden />}
      </div>
      <p className="text-md font-semibold">{title}</p>
      {description ? <p className="max-w-70 text-sm text-muted-foreground">{description}</p> : null}
      {primaryAction || secondaryAction ? (
        <div className="mt-1.5 flex items-center gap-2">
          {secondaryAction}
          {primaryAction}
        </div>
      ) : null}
    </div>
  );
}
